INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('2 Valid IDs', '2 Valid IDs', '2-valid-ids-2026', 'Sylvia, a poor farmer, is unable to claim the money sent to her because she lacks the required two valid IDS. In her struggle to secure the IDs, Sylvia finds herself in a situation that challenges her character, beliefs, and morality.', '2026-01-01', 2026, 'assets/2-valid-ids.jpeg', 'https://letterboxd.com/film/2-valid-ids/', '{"cinemalaya","indie","drama"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
