INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Ganggang', 'Ganggang', 'ganggang-2026', 'At the first clash of their fighting spiders, Ilay and Ten-ten knew they would go home as losers. Anton, the winner of the fight, will once again lord over their school. At the sideline is Mel, a newcomer and a city boy, watching the rowdy play in awe, unaware that soon he will become an ally of Ilay and Ten-ten against the real neighborhood bully.', '2026-01-01', 2026, 'assets/ganggang.jpg', 'https://letterboxd.com/film/ganggang/', '{"cinemalaya","indie","drama"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
