INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('ANi (The Harvest)', 'ANi (The Harvest)', 'ani-the-harvest-2019', 'Set in the year 2050 at the State of Bicol, Philippines, Mithi,an orphaned boy moves to a farm to live with his estranged grandfather, Mauricio. When the old man falls ill, and as thecrops in their farm seem to fall ill with him, the boy embarkson a quest with his malfunctioning robot to search for magicalgrains that he believes can save the man’s life.', '2019-01-01', 2019, 'assets/ani.jpg', 'https://letterboxd.com/film/ani-2019/', '{"cinemalaya","indie","sci-fi","fantasy"}', '[{"type":"iwant"},{"type":"appletv"},{"type":"youtube","url":"https://www.youtube.com/watch?v=kSG8O0HdqpE"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
