INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Belle Douleur (A Beautiful Pain)', 'Belle Douleur (A Beautiful Pain)', 'belle-douleur-a-beautiful-pain-2019', 'Liz, a 45-year-old, single clinical psychologist finds herself alone and resigned to a solitary life after her parents passed away. Advised by her friends, Liz begins downsizing her home and meets Josh, a young antique dealer, who has been living on his own for years after losing his father and grandfather, and without much memory of his mother.', '2019-01-01', 2019, 'assets/belle.jpg', 'https://letterboxd.com/film/belle-douleur/', '{"cinemalaya","indie","drama"}', '[{"type":"appletv"},{"type":"iwant"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
