INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Malamaya (The Color of Ash)', 'Malamaya (The Color of Ash)', 'malamaya-the-color-of-ash-2019', 'Nora Simeon, a 50-year old, single visual artist, feels passe. As she tries to recapture her prime, she finds spark with Migs, an aspiring photographer who helps re-ignite her forgotten passions. As she embarks on a May-December love affair, Nora fails to notice how Migs invades her space and senses, and eventually, her art and body.', '2019-01-01', 2019, 'assets/malamaya.jpg', 'https://letterboxd.com/film/the-color-of-ash/', '{"cinemalaya","indie","romance","drama"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
