INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Pandanggo sa Hukay', 'Pandanggo sa Hukay', 'pandanggo-sa-hukay-2019', 'Elena, a midwife and breadwinner, aims for a better future for her family. On the eve of her application process and interview for an overseas job, Elena finds herself in a nun familiar territory and dances her way out: the pandanggo way.', '2019-01-01', 2019, 'assets/hukay.jpg', 'https://letterboxd.com/film/pandanggo-sa-hukay/', '{"cinemalaya","indie","drama","crime"}', '[{"type":"iwant"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
