INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('ML', 'ML', 'ml-2018', 'Carlo, an unapologetically millennial college jock, thinks that Martial Law wasn’t all that bad. No one in his family had anything bad to say about it, all he’s ever read are online posts on human rights violations. Confronted by a frustrated History professor, Carlo sets out to prove he is right and looks for someone who lived through that period to tell the tale.', '2018-01-01', 2018, 'assets/ml.jpg', 'https://letterboxd.com/film/ml/', '{"cinemalaya","indie","thriller"}', '[{"type":"youtube","url":"https://www.youtube.com/watch?v=ZYpNhcHi85I&pp=ygUHTUwgMjAxOA%3D%3D"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
