INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('School Service', 'School Service', 'school-service-2018', 'Maya was walking home in her province when the service stops beside her and offers her to hitch. She innocently takes the ride to reach home faster. To Maya’s horror, the service did not stop at her place. She soon realizes she has been taken, along with the other kids who are inside the crammed school service.', '2018-01-01', 2018, 'assets/school-service.jpg', 'https://letterboxd.com/film/school-service/', '{"cinemalaya","indie","drama"}', '[{"type":"youtube","url":"https://www.youtube.com/watch?v=qcn3WHvmxi8"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
