INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Pan de Salawal', 'Pan de Salawal', 'pan-de-salawal-2018', 'A special little homeless girl travels about the Philippines curing the afflicted with her mysterious healing powers, until one day she befriends a sick old man who for some perplexing reason she is unable to cure. The unlikely pair are drawn to each other and their lives are forever changed by their unique friendship and magical journey together.', '2018-01-01', 2018, 'assets/pan-de-salawal.jpg', 'https://letterboxd.com/film/the-sweet-taste-of-salted-bread-and-undies/', '{"cinemalaya","indie","drama","comedy"}', '[{"type":"netflix"},{"type":"ccp"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
