INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Kuya Wes', 'Kuya Wes', 'kuya-wes-2018', 'Wes is a timid and earnest remittance clerk who feels non-existent and mostly ignored by his younger brother Raf and his family. His days are only brightened when his customer Erika, comes in every month. One day, his life changes as Erika’s overseas husband leaves her. Distraught and in need, Wes decides to help her out.', '2018-01-01', 2018, 'assets/wes.jpg', 'https://letterboxd.com/film/kuya-wes/', '{"cinemalaya","indie","drama","comedy"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
