INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Bagahe', 'Bagahe', 'bagahe-2017', 'Bagahe follows Mercy Agbunag, an Overseas Filipino Worker whose homecoming is interrupted when she is questioned about a newborn baby found in an airplane toilet. As she is passed between the police, hospital, shelter, media, church, and government agencies, the investigation uncovers the truth about her abuse and the way she is treated by the society she returns to.', '2017-01-01', 2017, 'assets/bagahe.jpg', 'https://letterboxd.com/film/the-baggage/', '{"cinemalaya","indie","drama"}', '[{"type":"juanflix"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
