INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Ang Guro Kong ''Di Marunong Magbasa', 'Ang Guro Kong ''Di Marunong Magbasa', 'ang-guro-kong-di-marunong-magbasa-2017', 'Set in war-torn southwestern Mindanao, the film follows Aaquil, a young farmer who becomes a teacher when volunteers from the city are too afraid to enter remote communities. When Aaquil disappears, his orphaned students turn to a rebel group and learn to fight, blaming others for the loss of their dreams.', '2017-01-01', 2017, 'assets/guro.jpg', 'https://letterboxd.com/film/my-teacher-who-doesnt-know-how-to-read/', '{"cinemalaya","indie","drama"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
