INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Ang Pamilyang Hindi Lumuluha', 'Ang Pamilyang Hindi Lumuluha', 'ang-pamilyang-hindi-lumuluha-2017', 'Cora, a wealthy landowner and media personality, searches for the mysterious “Family That Doesn’t Weep,” believed to have the power to bring lost loved ones back to their families. Hoping to reunite with her estranged husband and children, she relentlessly tracks down the elusive family in search of a miracle.', '2017-01-01', 2017, 'assets/lumuluha.jpg', 'https://letterboxd.com/film/the-family-that-doesnt-weep/', '{"cinemalaya","indie","drama","fantasy"}', '[{"type":"viva"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
