INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Sa Gabing Nanahimik ang mga Kuliglig', 'Sa Gabing Nanahimik ang mga Kuliglig', 'sa-gabing-nanahimik-ang-mga-kuliglig-2017', 'On Good Friday, Father Romi is confronted with a moral dilemma when Magda confesses to murdering her friend Dolores after discovering her affair with Victor. With only the altar boy Nonoy overhearing the confession, the two must wrestle with the burden of knowing the truth while honoring the sacred Seal of the Confessional.', '2017-01-01', 2017, 'assets/kuliglig.jpg', 'https://letterboxd.com/film/sa-gabing-nanahimik-ang-mga-kuliglig/', '{"cinemalaya","indie","drama"}', '[{"type":"ccp"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
