INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Lando at Bugoy', 'Lando at Bugoy', 'lando-at-bugoy-2016', 'Set in Camiguin Island, the film follows 40-year-old Lando, a gravestone maker, and his 15-year-old son Bugoy, who has stopped attending school. When Bugoy agrees to return only if his father also goes back to school, Lando becomes the unlikely student and the target of ridicule. As father and son navigate their struggles, an unexpected event changes their lives.', '2016-01-01', 2016, 'assets/lando.jpg', 'https://letterboxd.com/film/lando-and-bugoy/', '{"cinemalaya","indie","drama"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
