INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Pamilya Ordinaryo', 'Pamilya Ordinaryo', 'pamilya-ordinaryo-2016', 'Pamilya Ordinaryo follows 16-year-old Jane and her boyfriend Aries, who survive by pickpocketing on the streets of Manila. Their lives change when they become teenage parents, but their newborn is stolen less than a month later. Desperate to get their child back, the young couple is pushed to take increasingly drastic measures.', '2016-01-01', 2016, 'assets/pamilya.jpg', 'https://letterboxd.com/film/ordinary-people-2016/', '{"cinemalaya","indie","drama"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
