INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Tuos', 'Tuos', 'tuos-2016', 'Pinailog, a revered binukot in a remote village in Antique, has spent her life confined to her home as the guardian of her community’s oral traditions. As modernization threatens the survival of the binukot tradition, her 15-year-old granddaughter Duwokan resists being chosen and struggles between preserving her heritage and embracing a changing world.', '2016-01-01', 2016, 'assets/tuos.jpg', 'https://letterboxd.com/film/the-pact-2016/', '{"cinemalaya","indie","drama"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
