INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Kasal', 'Kasal', 'kasal-2014', 'Kasal is a slice of life drama of a gay couple whose resolve to stay together is challenged as they attend a wedding. It also is an examination on how a gay couple navigates through the different institutions in Philippine society.', '2014-01-01', 2014, 'assets/kasal.jpg', 'https://letterboxd.com/film/the-commitment-2014/', '{"cinemalaya","indie","drama","romance"}', '[{"type":"juanflix"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
