INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Hustisya', 'Hustisya', 'hustisya-2014', 'Biring, a foul-mouthed woman working for a human trafficking syndicate, is framed for a murder committed by her employer Vivian and forced to confront the corruption and injustice surrounding her. As she struggles through the broken justice system, her lawyer Gerald transforms her from victim into victimizer, leading her down a dark path until she becomes like the woman who betrayed her.', '2014-01-01', 2014, 'assets/hustisya.jpg', 'https://letterboxd.com/film/hustisya/', '{"cinemalaya","indie","drama","family","crime"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
