INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Mariquina', 'Mariquina', 'mariquina-2014', 'Mariquina follows successful businesswoman Imelda as she prepares for the funeral of her estranged father, Romeo, a once-renowned shoemaker whose career and family fell apart. Her search for the perfect final pair of shoes forces her to confront painful memories, her mother’s departure, and the complicated relationship she had with her father. Through their story, the film explores family, identity, loss, and the rise and decline of Marikina’s shoemaking industry.', '2014-01-01', 2014, 'assets/mariquina.jpg', 'https://letterboxd.com/film/mariquina/', '{"cinemalaya","indie","drama"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
