INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Ekstra (The Bit Player)', 'Ekstra (The Bit Player)', 'ekstra-the-bit-player-2013', 'A socio-realist drama-comedy ﬁlm, it follows a seemingly usual day in the life of Loida Malabanan as she embarks on yet another shooting day of a soap opera as an extra. As the shoot goes on, we get a glimpse of the truth in the ruling system of the production as well as the exploitation of the marginalized laborers like her.', '2013-01-01', 2013, 'assets/ekstra.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"youtube","url":"https://www.youtube.com/watch?v=GO6F1l-L9d4"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
