INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Instant Mommy', 'Instant Mommy', 'instant-mommy-2013', 'Instant Mommy follows the story of Bechayda, a two-months-pregnant wardrobe assistant for TV commercial production. In the fear of losing her Japanese lover and her dreams of a better life, she embarks on a plan that will get herself out of her predicament. Or so she thinks.', '2013-01-01', 2013, 'assets/instant-mommy.png', NULL, '{"cinemalaya","indie"}', '[{"type":"youtube","url":"https://www.youtube.com/watch?v=Nz7scr8xn_g"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
