INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Debosyon', 'Debosyon', 'debosyon-2013', 'Mando, a devotee of the Virgin of Peñafrancia, injures himself in the forest and is nursed by Salome, with whom he falls in love. When she refuses to leave due to a curse and a devastating secret, Mando turns to his faith to break it.', '2013-01-01', 2013, 'assets/debosyon.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"juanflix"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
