INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Quick Change', 'Quick Change', 'quick-change-2013', 'Dorina, a transgender woman who runs an illegal cosmetic surgery business, finds fulfillment as a career woman, wife, and mother figure to her young nephew. Her seemingly happy life is shaken when her husband Uno falls in love with another trans woman, forcing Dorina to confront love, identity, and betrayal.', '2013-01-01', 2013, 'assets/quick.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
