INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('David F.', 'David F.', 'david-f-2013', 'David F. weaves together three stories exploring the history and experiences of African Americans in the Philippines, from the Philippine-American War to the former Clark Air Base. Through the lives of a Black American soldier, a Filipina mother whose child is born Black during the Japanese Occupation, and a gay impersonator searching for his absent father, the film examines racism, discrimination, identity, and Filipino prejudice.', '2013-01-01', 2013, 'assets/david.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
