INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Kalayaan (Wildlife)', 'Kalayaan (Wildlife)', 'kalayaan-wildlife-2012', 'Julian, a soldier stationed on a remote Philippine island, is forced to extend his stay after news of a coup d’état in Manila reaches his base. When he loses contact with the main base and begins sensing someone watching him, two soldiers arrive to investigate and recount the strange story of a former soldier who claimed to have encountered a mermaid.', '2012-01-01', 2012, 'assets/kalayaan.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"appletv"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
