INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Patikul', 'Patikul', 'patikul-2011', 'The long-standing conflict between the military forces and the rebel group Abu Sayaff has severely ravaged the poor town of Patikul in Sulu. Residents have become so accustomed to the armed clashes, that reports of kidnappings and recruitment of young Tausugs to join the rebel groups already became normal news to them. However, Amman, a 33 year old coffee farmer in Sitio Kan-Ague, continues to believe that there is still hope for their town.', '2011-01-01', 2011, 'assets/patikul.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"youtube","url":"https://www.youtube.com/watch?v=ew80dXDbNMA&pp=ygUHcGF0aWt1bA%3D%3D"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
