INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Busong', 'Busong', 'busong-2011', 'Punay was born with wounds on her feet so that she cannot step on the earth. Her brother, Angkarang, carries her through a hammock, as he searches the changing landscape of Palawan in hoping to find a healer who can cure Punay. Different people help him carry his sister along the way- a woman looking for her husband, a fisherman who lost his boat, and a young man who is searching for himself- and each one meets their fate.', '2011-01-01', 2011, 'assets/busong.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
