INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Teoriya', 'Teoriya', 'teoriya-2011', 'Teoriya is a story about loss that centers on the film’s main character, Jimmuel Apostol II. After hearing the news that his father has passed away, Jim goes back home to Zamboanga City after leaving ten years ago in bad terms with his father. He arrives in Zamboanga only to find that his father has already been buried and he doesn’t know where.', '2011-01-01', 2011, 'assets/teoriya.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"none"}]'::jsonb, 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
