INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Mayohan', 'Mayohan', 'mayohan-2010', 'Mayohan is set in Infanta, Quezon where locals turn each of the 31 days of May into a charming celebration of good harvest and a tribute to the virginal virtues of Mary, mother of Christ. Amidst the festivities, Niño, a 15-year-old young outsider becomes involved in the preparation of the Mayohan’s final event, the pasayaw.', '2010-01-01', 2010, 'assets/mayohan.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"youtube","url":"https://www.youtube.com/watch?v=sQRnTbPER4Q&pp=ygUHbWF5b2hhbg%3D%3D"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
