INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Ang Paglilitis ni Andres Bonifacio', 'Ang Paglilitis ni Andres Bonifacio', 'ang-paglilitis-ni-andres-bonifacio-2010', 'Ang Paglilitis ni Andres Bonifacio is the untold story of the trial of Andres Bonifacio under the Revolutionary Government of Pres. Emilio Aguinaldo. Two leaders, Andres Bonifacio, Supremo of the Katipuneros, and Emilio Aguinaldo, president of the Revolutionary Government, made their way to fight for freedom for the Filipinos against the dominant rule, fought for a cause and for a reason to be one nation.', '2010-01-01', 2010, 'assets/andres.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"youtube","url":"https://www.youtube.com/watch?si=g_kVdKy5gv3ak7-O&v=pGbL-zXDqew&feature=youtu.be"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
