INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('The Leaving', 'The Leaving', 'the-leaving-2010', 'The Leaving explores the constant cycle of change, departure, and return through the lives of a new generation of Tsinoys (Filipino-Chinese). Set in a neo-Chinatown in Manila, the film follows three interconnected stories that portray their struggles with identity, relationships, and the fading of their cultural heritage.', '2010-01-01', 2010, 'assets/leaving.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"none"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
