INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Sampaguita, National Flower', 'Sampaguita, National Flower', 'sampaguita-national-flower-2010', 'This film tells the story of a group of children whose lives are inexorably bound up with Sampaguita the national flower of Philippines and the myths that surround it. Sampaguita blossoms are much sought-after but, since they wilt quickly, they must be sold within twenty-four hours. All the children in this film are are all sampaguita pickers or sellers.', '2010-01-01', 2010, 'assets/sampaguita.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"alexanderstreet"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
