INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Boses', 'Boses', 'boses-2008', 'Boses (Voices) is the story of a musician named Ariel who offers violin lessons to a child of the slums. Through the violin, the abused child Onyok is able to get back his voice from a mute, desensitized existence. A violin teacher and his student, a mute 7-year old abused child in a shelter, develop a friendship stemming from their love of music.', '2008-01-01', 2008, 'assets/boses.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"none"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
