INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Gulong (The Bicycle)', 'Gulong (The Bicycle)', 'gulong-the-bicycle-2007', 'Gulong is about friendship, love and life. The story is told from the point-of-view of Apao, a smart, kindhearted boy whose quest for an old bicycle reveals the stuff he is made of.', '2007-01-01', 2007, 'assets/gulong.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"ccp"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
