INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Kadin (The Goat)', 'Kadin (The Goat)', 'kadin-the-goat-2007', 'Peping wakes up to find out that Gima, their goat, is missing. His family make a living out of the milk provided the goat. He hides the truth from his grandmother. His father is also arriving the next day so he needs to find Gima before its too late. Together with his younger sister, Lita, the two go on a seemingly impossible search for the goat in the landscape of the island of Sabtang, in Batanes.', '2007-01-01', 2007, 'assets/kading.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"alexanderstreet"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
