INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Rotonda', 'Rotonda', 'rotonda-2006', 'Beginning at the break of dawn and ending the next morning, the story, set around a rugged city intersection, follows the path of a marked one-thousand-peso bill as it transfers from one character to another, returning to its originator in the end, blood-tainted. The money leads us to each of the five offbeat characters, all in desperate need of their soul’s redemption.', '2006-01-01', 2006, 'assets/rotonda.jpg', NULL, '{"cinemalaya","indie"}', '[{"type":"none"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
