INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, watch_sources, language, is_classic) VALUES ('Lasponggols (Last Take, Last Shot)', 'Lasponggols (Last Take, Last Shot)', 'lasponggols-last-take-last-shot-2005', 'A black comedy film, which focuses on two film workers, Raffy, the clapper, and Dido, a utility boy. Both share the same dream: to direct their own films someday. Their lives as mere “small production people” took a different turn when, together with the people in the unit van they were riding,had an encounter with armed men.', '2005-01-01', 2005, 'assets/lasponggols.jpg', 'https://letterboxd.com/film/last-take-last-shot/', '{"cinemalaya","indie","comedy","drama"}', '[{"type":"youtube","url":"https://www.youtube.com/watch?si=rudMdi6yyzgxScSC&v=MEUzhQV5UxA&feature=youtu.be"}]'::jsonb, 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
